using Cosmix.Application.Authentication;
using Cosmix.Application.HR.StaffCategories;
using Cosmix.Domain.Common.Approvals;
using Cosmix.Domain.HR.Policies;
var count=0;
void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);count++;}
void Reject(Action action,string code,string name){try{action();throw new Exception("FAIL: "+name);}catch(AuthenticationFailure e){Check(e.Code==code,name+": "+e.Code);}}
StaffTaxonomyPolicyReference[] References()=>Enum.GetValues<StaffTaxonomyPolicyUse>().Select(u=>new StaffTaxonomyPolicyReference(u,StaffTaxonomyPolicyApplicability.NotApplicable,null)).ToArray();
var rules=new StaffTaxonomyRules(1,[new("SITE","Site",StaffWorkLocation.Site,StaffScheduleBasis.Site,false,true,References()),new("OFFICE","Office",StaffWorkLocation.Office,StaffScheduleBasis.Office,false,false,References()),new("DRIVER","Synthetic driver",StaffWorkLocation.Site,StaffScheduleBasis.Site,true,true,References())]);
var canonical=StaffTaxonomyRulesCodec.Canonicalize(rules);var date=new DateOnly(2026,10,16);
if(args.Contains("http-only")){Console.WriteLine($"PASS: {await HttpChecks.Run(rules)} raw taxonomy HTTP body checks.");return;}
Check(StaffTaxonomyRulesCodec.Canonicalize(StaffTaxonomyRulesCodec.Parse(canonical))==canonical,"canonical roundtrip");
Check(StaffTaxonomyRulesCodec.Normalize(rules).Categories.First().Code=="DRIVER","stable canonical sorting");
Reject(()=>StaffTaxonomyRulesCodec.Parse(canonical.Replace("\"schemaVersion\":1","\"schemaVersion\":1,\"unknown\":1")),"invalid_staff_taxonomy_rules","unknown member");
Reject(()=>StaffTaxonomyRulesCodec.Parse(canonical.Replace("\"schemaVersion\":1","\"schemaVersion\":1,\"schemaVersion\":1")),"invalid_staff_taxonomy_rules","duplicate JSON member");
Reject(()=>StaffTaxonomyRulesCodec.Parse(canonical.Replace("\"outsideOvertimeInheritance\":true,","")),"invalid_staff_taxonomy_rules","missing explicit boolean");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c.Code=="DRIVER"?c with{Code=new string('D',31)}:c).ToArray()}),"invalid_staff_taxonomy_rules","category 30 character limit");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c.Code=="OFFICE"?c with{OutsideOvertimeInheritance=true}:c).ToArray()}),"staff_taxonomy_confirmed_baseline_changed","OFFICE OT deny retained");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c.Code=="SITE"?c with{RequireSiteBeforeActivation=true}:c).ToArray()}),"staff_taxonomy_confirmed_baseline_changed","SITE initial assignment optional retained");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c.Code=="DRIVER"?c with{ScheduleBasis=StaffScheduleBasis.Office}:c).ToArray()}),"invalid_staff_taxonomy_rules","mixed schedule/location unavailable");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Append(rules.Categories[0] with{Code="site"}).ToArray()}),"invalid_staff_taxonomy_rules","duplicate category canonical code");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c with{PolicyReferences=c.PolicyReferences.Take(4).ToArray()}).ToArray()}),"invalid_staff_taxonomy_rules","missing explicit applicability");
Reject(()=>StaffTaxonomyRulesCodec.Normalize(rules with{Categories=rules.Categories.Select(c=>c with{PolicyReferences=c.PolicyReferences.Select(r=>r with{Applicability=StaffTaxonomyPolicyApplicability.Required}).ToArray()}).ToArray()}),"invalid_staff_taxonomy_rules","required policy has immutable reference");
var office=StaffTaxonomyResolver.Resolve("OFFICE",date,[]);var site=StaffTaxonomyResolver.Resolve("SITE",date,[]);
Check(office.Available&&office.Baseline&&!office.Mapping!.OutsideOvertimeInheritance,"no publications OFFICE baseline");
Check(site.Available&&site.Baseline&&site.Mapping!.OutsideOvertimeInheritance,"no publications SITE baseline");
Check(!StaffTaxonomyResolver.Resolve("DRIVER",date,[]).Available,"broader unconfigured category unavailable");
Check(!StaffTaxonomyResolver.Resolve("OFFICE",date,[],true).Available,"publication namespace flag suppresses baseline");
StaffTaxonomyResolver.ValidateLocation(office,null,null,StaffTaxonomyValidationPhase.Draft);count++;
Reject(()=>StaffTaxonomyResolver.ValidateLocation(office,null,null,StaffTaxonomyValidationPhase.Activation),"staff_taxonomy_location_required","OFFICE activation branch required");
Reject(()=>StaffTaxonomyResolver.ValidateLocation(office,Guid.NewGuid(),Guid.NewGuid(),StaffTaxonomyValidationPhase.Draft),"staff_taxonomy_location_conflict","OFFICE never fabricated site");
StaffTaxonomyResolver.ValidateLocation(site,null,null,StaffTaxonomyValidationPhase.Activation);count++;
Reject(()=>StaffTaxonomyResolver.ValidateLocation(site,null,null,StaffTaxonomyValidationPhase.ScheduledDuty),"staff_taxonomy_location_required","SITE schedule needs site");
Reject(()=>StaffTaxonomyResolver.ValidateLocation(site,Guid.NewGuid(),null,StaffTaxonomyValidationPhase.Draft),"staff_taxonomy_location_conflict","SITE office prohibited");
Check(StaffTaxonomyResolver.MissingLocationFields(office,null,null,StaffTaxonomyValidationPhase.Activation).Single()=="branchId","exact missing field");
StaffTaxonomyVersionSource Source(DateOnly from,DateOnly? to,int n,Policy? p=null,string? schema=null){p??=new(StaffTaxonomyRulesCodec.PolicyCode,"Staff taxonomy",PolicyCategory.EmployeeException);var now=new DateTimeOffset(2026,10,13,7,0,0,TimeSpan.Zero);var request=new ApprovalRequest(StaffTaxonomyRulesCodec.RequestType,p.Id,Guid.NewGuid().ToString(),"synthetic-private",1,now);var decision=request.Decide(ApprovalState.Approved,Guid.NewGuid().ToString(),"ADMIN","synthetic approval",now);var version=new PolicyVersion(p.Id,n,from,to,schema??StaffTaxonomyRulesCodec.Schema,canonical,"synthetic-private",request.Id,decision.ActorUserId,now);return new(p,version,request,[decision],true);}
var source=Source(new(2026,10,15),null,1);
Check(StaffTaxonomyResolver.Resolve("DRIVER",date,[source]).Mapping!.RequireSiteBeforeActivation,"explicit broader mapping");
Check(!StaffTaxonomyResolver.Resolve("RIDER",date,[source]).Available,"unmapped category under publication unavailable");
var beforeFirst=StaffTaxonomyResolver.Resolve("OFFICE",new(2026,10,14),[source]);
Check(beforeFirst.Available&&beforeFirst.Baseline,"first future publication preserves confirmed historical OFFICE assignments");
Check(beforeFirst.Fingerprint==office.Fingerprint,"historical baseline fingerprint stays frozen after first future publication");
Check(!StaffTaxonomyResolver.Resolve("DRIVER",new(2026,10,14),[source]).Available,"new code unavailable before first effective date");
Check(!StaffTaxonomyResolver.Resolve("OFFICE",new(2026,10,14),[source with{EvidenceValid=false}]).Available,"invalid future publication does not restore baseline");
var inactiveFuture=Source(new(2026,10,20),null,1);inactiveFuture.Policy.Deactivate();
Check(!StaffTaxonomyResolver.Resolve("OFFICE",date,[inactiveFuture]).Available,"inactive future publication does not restore baseline");
Check(!StaffTaxonomyResolver.Resolve("OFFICE",date,[Source(new(2026,10,14),new(2026,10,16),1)]).Available,"expired publication no fallback");
var inactive=Source(new(2026,10,14),null,1);inactive.Policy.Deactivate();Check(!StaffTaxonomyResolver.Resolve("OFFICE",date,[inactive]).Available,"inactive publication no fallback");
Check(!StaffTaxonomyResolver.Resolve("OFFICE",date,[Source(new(2026,10,14),null,1,source.Policy),Source(new(2026,10,15),new(2026,10,16),2,source.Policy)]).Available,"expired successor cannot restore old open version");
Check(StaffTaxonomyResolver.Resolve("OFFICE",date,[source,source]).State=="ambiguous_taxonomy","same-date sources ambiguous");
Check(StaffTaxonomyResolver.Resolve("OFFICE",date,[source with{EvidenceValid=false}]).State=="invalid_taxonomy_evidence","invalid evidence visible");
Check(StaffTaxonomyResolver.Resolve("OFFICE",date,[Source(new(2026,10,15),null,1,schema:"unknown")]).State=="invalid_taxonomy_evidence","unknown schema failclosed");
Check(StaffTaxonomyResolver.Resolve("DRIVER",date,[source]).Fingerprint==StaffTaxonomyResolver.Resolve("DRIVER",date,[source,Source(new(2026,10,20),null,2,source.Policy)]).Fingerprint,"future append preserves earlier identity");
Reject(()=>new StaffTaxonomyAuthority(new()).Require(new(2026,10,13),date),"staff_taxonomy_authority_approval_required","authority defaults unavailable");
Reject(()=>new StaffTaxonomyAuthority(new(){Mode=StaffTaxonomyAuthorityMode.IndependentFixedAdministrator}).Require(new(2026,10,13),date),"staff_taxonomy_authority_approval_required","authority version/effective required");
var authority=new StaffTaxonomyAuthority(new(){Mode=StaffTaxonomyAuthorityMode.IndependentFixedAdministrator,ApprovedVersion="synthetic-authority",EffectiveFrom=new(2026,1,1)});
var stamp=authority.Require(new(2026,10,13),date);Check(stamp.ApprovedVersion=="synthetic-authority","authority exact stamp retained");
Reject(()=>new StaffTaxonomyAuthority(new(){Mode=StaffTaxonomyAuthorityMode.IndependentFixedAdministrator,ApprovedVersion="expired",EffectiveFrom=new(2026,1,1),EffectiveTo=new(2026,10,13)}).Require(new(2026,10,13),date),"staff_taxonomy_authority_approval_required","expired authority failclosed");
Check(StaffTaxonomyAuthority.Valid(stamp,new(2026,10,13),date),"historical stamp valid");
Reject(()=>StaffTaxonomyResolver.ParseReference("{\"StorageKey\":\"s\",\"ObjectVersion\":\"1\",\"KeyReference\":\"k\",\"SizeBytes\":1}"),"staff_taxonomy_evidence_invalid","malformed private metadata failclosed");
count+=await ServiceChecks.Run(rules);
count+=await HttpChecks.Run(rules);
Console.WriteLine($"PASS: {count} taxonomy checks; no SQL/provider/account mutation.");
